// Mind Rewind's static data, cut from the depacked MINDWIND.TOS by
// prototypes/mindwind_re/scripts/cart_data.py (art, tables, palettes, text; the
// buffers the demo GENERATES are generated by stripes_gen.zig / rainbow_gen.zig).
// Big-endian, as in the binary.
const std = @import("std");

const DIR = "../../assets/screens/mindwind/";
pub const stripe_patterns = @embedFile(DIR ++ "stripe_patterns.bin"); // $317C - 16p
pub const sin_208c = @embedFile(DIR ++ "sin_208c.bin"); // 1024 words 0..511
pub const tab_288c = @embedFile(DIR ++ "tab_288c.bin"); // 1024 words 0..31
pub const sin_271c8 = @embedFile(DIR ++ "sin_271c8.bin"); // sin x 32767
pub const sin_b61a = @embedFile(DIR ++ "sin_b61a.bin"); // sin x 16384, 512 words
pub const flip = @embedFile(DIR ++ "flip_3e496.bin"); // 90 x 200 words
pub const wobble_script = @embedFile(DIR ++ "wobble_script.bin");
pub const girl = @embedFile(DIR ++ "girl.bin"); // 320x200 planar
pub const girl_pal = @embedFile(DIR ++ "girl.pal");
pub const rg_end = @embedFile(DIR ++ "rg_end.bin");
pub const rg_end_pal = @embedFile(DIR ++ "rg_end.pal");
pub const band = @embedFile(DIR ++ "band.bin"); // 320x42 planar, 192 px used
pub const band_pal = @embedFile(DIR ++ "band.pal");
pub const pal_stripes = @embedFile(DIR ++ "pal_stripes.pal");
pub const pal_rainbow = @embedFile(DIR ++ "pal_rainbow.pal");
pub const pal_scroller = @embedFile(DIR ++ "pal_scroller.pal");
pub const bars = @embedFile(DIR ++ "bars.bin"); // 31 words: the bars' 14-line window slides over them
pub const lines_41a4 = @embedFile(DIR ++ "lines_41a4.bin"); // u16 LE stripe rows
pub const lines_42a4 = @embedFile(DIR ++ "lines_42a4.bin");
pub const font = @embedFile(DIR ++ "font.bin"); // 16-px planar columns, 48 rows of 8 bytes
pub const font_ptrs = @embedFile(DIR ++ "font_ptrs.bin"); // u16 LE byte offset per char 0..90
pub const scrolltext = @embedFile(DIR ++ "scrolltext.bin"); // 0, text, 0

pub inline fn be16(b: []const u8, i: usize) u16 {
    return std.mem.readInt(u16, b[2 * i ..][0..2], .big);
}
pub inline fn le16(b: []const u8, i: usize) u16 {
    return std.mem.readInt(u16, b[2 * i ..][0..2], .little);
}
pub fn palette(b: *const [32]u8) [16]u16 {
    var p: [16]u16 = undefined;
    for (0..16) |i| p[i] = be16(b, i);
    return p;
}
